(function(){
  try {
    function findInput(selector) {
      let el = document.querySelector(selector);
      if (el) return el;
      const all = document.querySelectorAll('*');
      for (let i = 0; i < all.length; i++) {
        if (all[i].shadowRoot) {
          el = all[i].shadowRoot.querySelector(selector);
          if (el) return el;
        }
      }
      return null;
    }

    const nameEl = findInput('#field-name');
    const addrEl = findInput('#field-address');
    const cityEl = findInput('#field-city');
    const zipEl = findInput('#field-zip');
    const cardEl = findInput('#field-card');
    const expEl = findInput('#field-expiry');
    const cvvEl = findInput('#field-cvv');
    const btnEl = document.querySelector('#place-order-btn') || findInput('#place-order-btn');

    if (nameEl) {
      nameEl.value = 'Jane Smith';
      nameEl.dispatchEvent(new Event('input', { bubbles: true }));
      nameEl.dispatchEvent(new Event('change', { bubbles: true }));
    }
    if (addrEl) {
      addrEl.value = '123 Test Lane';
      addrEl.dispatchEvent(new Event('input', { bubbles: true }));
      addrEl.dispatchEvent(new Event('change', { bubbles: true }));
    }
    if (cityEl) {
      cityEl.value = 'Anytown';
      cityEl.dispatchEvent(new Event('input', { bubbles: true }));
      cityEl.dispatchEvent(new Event('change', { bubbles: true }));
    }
    if (zipEl) {
      zipEl.value = '00000';
      zipEl.dispatchEvent(new Event('input', { bubbles: true }));
      zipEl.dispatchEvent(new Event('change', { bubbles: true }));
    }
    if (cardEl) {
      cardEl.value = '4111111111111111';
      cardEl.dispatchEvent(new Event('input', { bubbles: true }));
      cardEl.dispatchEvent(new Event('change', { bubbles: true }));
    }
    if (expEl) {
      expEl.value = '12/28';
      expEl.dispatchEvent(new Event('input', { bubbles: true }));
      expEl.dispatchEvent(new Event('change', { bubbles: true }));
    }
    if (cvvEl) {
      cvvEl.value = '123';
      cvvEl.dispatchEvent(new Event('input', { bubbles: true }));
      cvvEl.dispatchEvent(new Event('change', { bubbles: true }));
    }

    if (btnEl) {
      btnEl.click();
      return 'Successfully filled form and clicked place order';
    } else {
      return 'Inputs found: ' + !!nameEl + ', but place-order-btn not found';
    }
  } catch(e) {
    return 'Error: ' + e.message;
  }
})()
